internal class MuscleRule(val pattern: Regex, val primary: List<String>, val secondary: List<String>)

private fun rule(pattern: String, primary: List<String>, secondary: List<String>) =
    MuscleRule(Regex(pattern, setOf(RegexOption.IGNORE_CASE)), primary, secondary)

